var maxLengthBetweenEqualCharacters = function(s) {
    const first = new Map();
    let ans = -1;
    for (let i = 0; i < s.length; ++i) {
        const c = s[i];
        if (!first.has(c)) {
            first.set(c, i);
        } else {
            ans = Math.max(ans, i - first.get(c) - 1);
        }
    }
    return ans;
};
